fn conditional_average(vals_1: &Vec<u64>, vals_2: &Vec<u64>, conds_1: &Vec<bool>, conds_2: &Vec<bool>, avgs: &mut Vec<u64>) {
    let len = vals_1.len();
    
    // Ensure avgs has the right length
    avgs.clear();
    avgs.reserve(len);
    
    for i in 0..len {
        let val1 = vals_1[i];
        let val2 = vals_2[i];
        let cond1 = conds_1[i];
        let cond2 = conds_2[i];
        
        let result = match (cond1, cond2) {
            (true, true) => (val1 + val2) / 2,
            (true, false) => val1,
            (false, true) => val2,
            (false, false) => {
                // According to problem, this case shouldn't happen
                // But we need to handle it to avoid panic
                0 // Default value, though assumption says at least one is true
            }
        };
        
        avgs.push(result);
    }
}